import { useRef, useReducer, memo } from "react";

type CountState = { n: number };
type Action = { type: "inc" } | { type: "dec" };

function reducer(state: CountState, action: Action): CountState {
  switch (action.type) {
    case "inc":
      return { n: state.n + 1 };
    case "dec":
      return { n: state.n - 1 };
  }
}

export function CounterReducer() {
  const [state, dispatch] = useReducer(reducer, { n: 0 });
  const inputRef = useRef<HTMLInputElement>(null);
  return (
    <>
      <p>{state.n}</p>
      <button type="button" onClick={() => dispatch({ type: "inc" })}>+</button>
      <input ref={inputRef} />
      <button type="button" onClick={() => inputRef.current?.focus()}>Focus</button>
    </>
  );
}
